From bc9570828ce1f8f7826178adf6e803714ca705e5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:20:13 +0100
Subject: [PATCH] applet: Keep the network list order while the pointer is over
 it

Scans update signal strengths and add networks all the time, so the list
re-sorted right under the pointer and a click could hit another network.
The order is now held while hovered, except when a connection changes.

BUG: 513116
---
 applet/ConnectionListPage.qml    |  5 +++++
 applet/PopupDialog.qml           |  1 +
 libs/models/appletproxymodel.cpp | 36 ++++++++++++++++++++++++++++++++
 libs/models/appletproxymodel.h   | 10 +++++++++
 4 files changed, 52 insertions(+)

diff --git a/applet/ConnectionListPage.qml b/applet/ConnectionListPage.qml
index b3b8d917e..07a8b803b 100644
--- a/applet/ConnectionListPage.qml
+++ b/applet/ConnectionListPage.qml
@@ -18,6 +18,7 @@ ColumnLayout {
     required property PlasmaNM.NetworkStatus nmStatus
     property alias model: connectionView.model
     property alias count: connectionView.count
+    readonly property alias hovered: listHoverHandler.hovered

     spacing: 0

@@ -60,6 +61,10 @@ ColumnLayout {

             property int currentVisibleButtonIndex: -1

+            HoverHandler {
+                id: listHoverHandler
+            }
+
             Keys.onDownPressed: event => {
                 connectionView.incrementCurrentIndex();
                 connectionView.currentItem.forceActiveFocus();
diff --git a/applet/PopupDialog.qml b/applet/PopupDialog.qml
index ab3e6b6a9..ce32709be 100644
--- a/applet/PopupDialog.qml
+++ b/applet/PopupDialog.qml
@@ -37,6 +37,7 @@ PlasmaExtras.Representation {
         id: appletProxyModel

         sourceModel: full.connectionModel
+        keepOrder: connectionListPage.hovered
     }

     header: PlasmaExtras.PlasmoidHeading {
diff --git a/libs/models/appletproxymodel.cpp b/libs/models/appletproxymodel.cpp
index eceab62c3..d2db878ca 100644
--- a/libs/models/appletproxymodel.cpp
+++ b/libs/models/appletproxymodel.cpp
@@ -20,6 +20,11 @@ AppletProxyModel::AppletProxyModel(QObject *parent)
     sort(0, Qt::DescendingOrder);

     connect(&Configuration::self(), &Configuration::manageVirtualConnectionsChanged, this, &AppletProxyModel::onManageVirtualConnectionsChanged);
+    connect(this, &QAbstractProxyModel::sourceModelChanged, this, [this] {
+        if (sourceModel()) {
+            connect(sourceModel(), &QAbstractItemModel::dataChanged, this, &AppletProxyModel::onSourceDataChanged);
+        }
+    });
 }

 AppletProxyModel::~AppletProxyModel() = default;
@@ -124,6 +129,37 @@ bool AppletProxyModel::lessThan(const QModelIndex &left, const QModelIndex &righ
     }
 }

+bool AppletProxyModel::keepOrder() const
+{
+    return m_keepOrder;
+}
+
+void AppletProxyModel::setKeepOrder(bool keepOrder)
+{
+    if (m_keepOrder == keepOrder) {
+        return;
+    }
+
+    m_keepOrder = keepOrder;
+    if (!m_keepOrder) {
+        beginFilterChange();
+        endFilterChange();
+    }
+    setDynamicSortFilter(!m_keepOrder);
+    Q_EMIT keepOrderChanged();
+}
+
+void AppletProxyModel::onSourceDataChanged(const QModelIndex &topLeft, const QModelIndex &bottomRight, const QList<int> &roles)
+{
+    Q_UNUSED(topLeft)
+    Q_UNUSED(bottomRight)
+
+    // Connecting or disconnecting is a user action, so its new position is applied right away
+    if (m_keepOrder && roles.contains(NetworkModel::ConnectionStateRole)) {
+        sort(0, Qt::DescendingOrder);
+    }
+}
+
 void AppletProxyModel::onManageVirtualConnectionsChanged()
 {
     beginFilterChange();
diff --git a/libs/models/appletproxymodel.h b/libs/models/appletproxymodel.h
index ba1a99ba6..91dad414d 100644
--- a/libs/models/appletproxymodel.h
+++ b/libs/models/appletproxymodel.h
@@ -18,16 +18,26 @@ class PLASMANM_INTERNAL_EXPORT AppletProxyModel : public QSortFilterProxyModel
     Q_OBJECT
     QML_ELEMENT
     Q_PROPERTY(QAbstractItemModel *sourceModel READ sourceModel WRITE setSourceModel)
+    Q_PROPERTY(bool keepOrder READ keepOrder WRITE setKeepOrder NOTIFY keepOrderChanged)
 public:
     explicit AppletProxyModel(QObject *parent = nullptr);
     ~AppletProxyModel() override;

+    bool keepOrder() const;
+    void setKeepOrder(bool keepOrder);
+
+Q_SIGNALS:
+    void keepOrderChanged();
+
 protected:
     bool filterAcceptsRow(int source_row, const QModelIndex &source_parent) const override;
     bool lessThan(const QModelIndex &left, const QModelIndex &right) const override;

 private:
     void onManageVirtualConnectionsChanged();
+    void onSourceDataChanged(const QModelIndex &topLeft, const QModelIndex &bottomRight, const QList<int> &roles);
+
+    bool m_keepOrder = false;
 };

 #endif // PLASMA_NM_APPLET_PROXY_MODEL_H
